    "content": "银行业理财登记托管中心最新数据显示，截至2026年6月末，理财产品投资资产合计36万亿元，其中公募基金配置规模2.52万亿元，占比较年初提升1.9个百分点，至7.0%、创历史新高，并跃居理财产品第四大资产类别，仅次于债券、现金及银行存款、同业存单。在传统优质资产供给收缩、市场收益承压、净值化转型深化的背景下，理财产品可借助债券型基金灵活调节组合久期，通过配置摊余成本法债基平滑净值波动，依托ETF实现权益资产高效布局，利用基金标准化交易机制提升调仓效率与资金运作效率。正是这一系列工具价值的释放，构成了近年来理财产品持…"
