    "link": "https://36kr.com/newsflashes/3925839652698505?f=rss",
    "pub_date": "2026-08-05 07:30:36",
    "author": "",
    "description": "马斯克周二为SpaceX勾勒了雄心勃勃的目标，包括在2027年将数据中心送入太空，以及实现1万亿美元的收入。这是该公司首次公开募股（IPO）以来，马斯克首次向投资者发表讲话。在与分析师长约一小时的电话会议中，马斯克宣传了公司的多项预期目标，例如SpaceX到2030年实现1万亿美元的收入，将原定于2031年达成该目标的时间表提前。马斯克和其他高管还向分析师强调，这些支出对于建设AI基础设施等公司战略至关重要。（新浪财经）",
    "content": "马斯克周二为SpaceX勾勒了雄心勃勃的目标，包括在2027年将数据中心送入太空，以及实现1万亿美元的收入。这是该公司首次公开募股（IPO）以来，马斯克首次向投资者发表讲话。在与分析师长约一小时的电话会议中，马斯克宣传了公司的多项预期目标，例如SpaceX到2030年实现1万亿美元的收入，将原定于2031年达成该目标的时间表提前。马斯克和其他高管还向分析师强调，这些支出对于建设AI基础设施等公司战略至关重要。（新浪财经）"
