    "title": "7月量化私募大回撤，幻方多只产品年内收益转负",
    "link": "https://36kr.com/newsflashes/3925372754737286?f=rss",
    "pub_date": "2026-08-05 07:24:30",
    "author": "",
    "description": "私募排排网最新数据显示，多家量化机构旗下产品在7月出现大面积、深幅度的回撤，部分产品年内收益由正转负，单月跌幅超过20%。具体来看，截至2026年7月31日，幻方量化旗下9只展示产品中，除九章幻方中证500量化多策略2号尚存0.04%的微弱年内正收益外，其余8只产品年内收益已全部告负。其中，幻方量化信淮500指数专项19号7期开年以来净值跌幅达3.84%。更令人关注的是月度表现，幻方旗下9只产品7月单月跌幅全部超过20%，最大回撤来自幻…",
    "content": "私募排排网最新数据显示，多家量化机构旗下产品在7月出现大面积、深幅度的回撤，部分产品年内收益由正转负，单月跌幅超过20%。具体来看，截至2026年7月31日，幻方量化旗下9只展示产品中，除九章幻方中证500量化多策略2号尚存0.04%的微弱年内正收益外，其余8只产品年内收益已全部告负。其中，幻方量化信淮500指数专项19号7期开年以来净值跌幅达3.84%。更令人关注的是月度表现，幻方旗下9只产品7月单月跌幅全部超过20%，最大回撤来自幻方中证500量化进取1号，单月净值下挫22.15%。（每经网）"
