    "pub_date": "2026-08-05 07:13:21",
    "author": "",
    "description": "记者从多家航空公司了解到，从今天(5日)起销售的国内航线机票燃油附加费再次下调。调整后的国内航线燃油附加费标准为：800公里以上航线每位成人旅客收取70元燃油附加费，800公里(含)以下航线每位成人旅客收取40元燃油附加费，相较于调整前分别降低了30元和10元。",
    "content": "记者从多家航空公司了解到，从今天(5日)起销售的国内航线机票燃油附加费再次下调。调整后的国内航线燃油附加费标准为：800公里以上航线每位成人旅客收取70元燃油附加费，800公里(含)以下航线每位成人旅客收取40元燃油附加费，相较于调整前分别降低了30元和10元。"
