    "description": "近期，菲律宾以所谓“新渔民英雄计划”为名，组织渔船频繁进入中国黄岩岛附近海域制造事端。菲方将普通渔民推至海上博弈前沿，将之包装成“海上卫士”“国家英雄”，刻意制造摩擦、炮制悲情叙事，不仅无助于改善本国民生，更持续扰动南海海域稳定，让无辜渔民沦为地缘政治的“群演”。 菲方此类海上造势操作由来已久，早已形成成熟套路。早在阿基诺三世政府时期，菲律宾便以民间自发为幌子，组织渔船非法进入中国南海相关海域，由官方执法船全程护航策应。2024年菲方拨…",
    "content": "近期，菲律宾以所谓“新渔民英雄计划”为名，组织渔船频繁进入中国黄岩岛附近海域制造事端。菲方将普通渔民推至海上博弈前沿，将之包装成“海上卫士”“国家英雄”，刻意制造摩擦、炮制悲情叙事，不仅无助于改善本国民生，更持续扰动南海海域稳定，让无辜渔民沦为地缘政治的“群演”。 菲方此类海上造势操作由来已久，早已形成成熟套路。早在阿基诺三世政府时期，菲律宾便以民间自发为幌子，组织渔船非法进入中国南海相关海域，由官方执法船全程护航策应。2024年菲方拨付专项经费，2025年5月马科斯政府正式推出所谓“新渔民英雄计划”，将相关挑衅行…"
