    "author": "张安宇、王崟欣/人民日报",
    "description": "“夏天，不仅人怕热，水稻也怕热，而且会减产。我们的研究，就是要让水稻耐热。”在上海市徐汇区，记者见到中国科学院院士、中国科学院分子植物科学卓越创新中心研究员林鸿宣时，他正在闷热的人工气候室内观察水稻长势。 “我们在这里模拟高温条件下水稻的长势情况。”林鸿宣边擦汗边介绍，他带领团队从非洲稻中提取“耐热”基因，通过长达20年的努力，实现特定品种水稻高温少减产。 盛夏时节，行走上海，切实感受到“以更大力度、更实举措加强基础研究，提升我国原始创…",
    "content": "“夏天，不仅人怕热，水稻也怕热，而且会减产。我们的研究，就是要让水稻耐热。”在上海市徐汇区，记者见到中国科学院院士、中国科学院分子植物科学卓越创新中心研究员林鸿宣时，他正在闷热的人工气候室内观察水稻长势。 “我们在这里模拟高温条件下水稻的长势情况。”林鸿宣边擦汗边介绍，他带领团队从非洲稻中提取“耐热”基因，通过长达20年的努力，实现特定品种水稻高温少减产。 盛夏时节，行走上海，切实感受到“以更大力度、更实举措加强基础研究，提升我国原始创新能力”的行动力，感受到这里科创活力奔涌的坚实底气。 底气，来自坐热“冷板凳”。…"
