    "content": "中新社首尔8月5日电 (记者 金旭)当地时间4日，韩国政府召开由总统李在明主持的国务会议，审议并通过《刑事诉讼法》修正案，全面取消检察机关直接侦查和补充侦查的权限。这意味着韩国延续70余年的刑事司法体系将迎来重大变革。"
