    "content": "新华社纽约8月4日电（记者刘亚南）受美国和伊朗或将很快达成涉霍尔木兹海峡协议乐观预期推动，国际原油期货价格4日早盘快速走低，盘中弱势盘整，收盘时国际油价显著下跌超5%。 截至当天收盘，纽约商品交易所9月交货的轻质原油期货价格下跌4.57美元，收于每桶75.77美元，跌幅为5.69%；10月交货的伦敦布伦特原油期货价格下跌4.41美元，收于每桶79.36美元，跌幅为5.26%。 据美国媒体4日报道，美国财政部长贝森特称，有关霍尔木兹海峡的协议可能在4日或5日达成。贝森特称：“就在当下，也能看到不少船只驶出霍尔木兹海峡…"
