    "content": "04/08/2026 - 17:49 据路透社援引三位知情人士报导称，美国陆军在与伊朗长达五个月的冲突中，已消耗了其大部分高精度远程导弹库存，这引发了人们对美军应对未来冲突的战备能力的担忧。 这些导弹主要包括美国陆军的地对地武器，即陆军战术导弹系统（ATACMS）和精确打击导弹（PrSM）。据其中两位消息人士称，美方已使用了“几乎所有”此类武器。此前尚未有关于美军陆军战术导弹系统和精确打击导弹库存即将耗尽程度的报道。 这些远程弹药单价超过100万美元，是美军武器库的重要组成部分，能够实现从安全距离发起的精确打击。美…"
