    "description": "背景 平时桌面和项目目录里文件夹数量一多，Finder 默认的蓝色文件夹在视觉上完全不可区分，找文件基本靠读文字，效率不高。想给文件夹换图标，macOS 原生支持但操作繁琐（复制粘贴图标、调整尺寸等），也没有一个轻量化的集中管理工具。 解决思路 做了一个小工具，核心逻辑是把「给文件夹贴图标」这件事流程化：选择文件夹 → 选择图标 → 一键应用。支持批量操作和一键还原。 功能 系统预设图标库，按场景分类 支持自定义图片作为图标源 一键应用…",
