    "title": "央行将开展5000亿元买断式逆回购操作",
    "link": "http://www.news.cn/20260804/8e9ab7f3698d414a9cdbeb05bc8c4bca/c.html",
    "pub_date": "2026-08-04 21:56:33",
    "author": "",
    "description": "中国人民银行8月4日发布消息称，为保持银行体系流动性充裕，中国人民银行将于8月5日以固定数量、利率招标、多重价位中标方式开展5000亿元买断式逆回购操作，期限为3个月（92天），到期日为2026年11月5日（遇节假日顺延）。 记者了解到，8月份将有3000亿元3个月期买断式逆回购到期。这意味着，当月3个月期买断式逆回购加量续作2000亿元。（记者任军、吴雨）",
    "content": "中国人民银行8月4日发布消息称，为保持银行体系流动性充裕，中国人民银行将于8月5日以固定数量、利率招标、多重价位中标方式开展5000亿元买断式逆回购操作，期限为3个月（92天），到期日为2026年11月5日（遇节假日顺延）。 记者了解到，8月份将有3000亿元3个月期买断式逆回购到期。这意味着，当月3个月期买断式逆回购加量续作2000亿元。（记者任军、吴雨）"
