    "title": "一管通冬夏 江苏徐州一地试行集中供冷",
    "link": "http://www.news.cn/20260804/7148bdd6c97849cfa6fae694da5ee968/c.html",
    "pub_date": "2026-08-04 21:42:59",
    "author": "毛俊",
    "description": "三伏天里，江苏徐州一小区不开空调，室温就能保持25摄氏度左右，这份夏日里的凉意源自一座已废弃的煤矿，井下积存的矿井水常年恒温十几摄氏度，如今顺着小区的供暖管道，流进了首批近100户居民的地暖盘管。 曾经的资源枯竭“包袱”，变成了惠及居民的“天然冷源”。据了解，该系统还可以通过热泵技术提取矿井水的热量，实现冬季集中供暖，从而实现一管通冬夏。 作者：毛俊、王振兴、孙智慧、王飞腾 摄制：张熠辉 新华社音视频部制作",
    "content": "三伏天里，江苏徐州一小区不开空调，室温就能保持25摄氏度左右，这份夏日里的凉意源自一座已废弃的煤矿，井下积存的矿井水常年恒温十几摄氏度，如今顺着小区的供暖管道，流进了首批近100户居民的地暖盘管。 曾经的资源枯竭“包袱”，变成了惠及居民的“天然冷源”。据了解，该系统还可以通过热泵技术提取矿井水的热量，实现冬季集中供暖，从而实现一管通冬夏。 作者：毛俊、王振兴、孙智慧、王飞腾 摄制：张熠辉 新华社音视频部制作"
