    "content": "新华社南昌8月4日电 江西省纪委监委8月4日通报，经江西省委批准，江西省纪委监委对省发展和改革委员会原党组成员，省粮食和物资储备局原党组书记、局长路文革严重违纪违法问题进行了立案审查调查。 经查，路文革丧失理想信念，背弃初心使命，政绩观错位，对抗组织审查，串供并转移、隐匿证据；无视中央八项规定精神，收受可能影响公正执行公务的礼品，接受可能影响公正执行公务的宴请和旅游活动安排；组织原则缺失，隐瞒不报个人有关事项，在组织谈话时不如实向组织说明问题，在职工录用工作中违规为他人谋取利益；廉洁底线失守，搞权权交易，违规组织、…"
