    "pub_date": "2026-08-04 21:16:54",
    "author": "",
    "description": "新华社北京8月4日电 伊拉克北部库尔德自治区（库区）主席巴尔扎尼3日到访叙利亚首都大马士革，会见叙过渡政府总统沙拉。消息人士说，巴尔扎尼此访意在推动叙库尔德武装加速整合进叙国家机构。 叙利亚总统府当天发表声明说，双方讨论了加强地区安全和经济合作以及“涉及双方共同利益的诸多事宜”。 巴尔扎尼在另一份声明中强调，他支持叙利亚“保持统一和稳定”。 叙利亚库尔德武装主导的“叙利亚民主力量”长期控制叙北部和东部大片地区，去年3月与叙过渡政府签署相…",
    "content": "新华社北京8月4日电 伊拉克北部库尔德自治区（库区）主席巴尔扎尼3日到访叙利亚首都大马士革，会见叙过渡政府总统沙拉。消息人士说，巴尔扎尼此访意在推动叙库尔德武装加速整合进叙国家机构。 叙利亚总统府当天发表声明说，双方讨论了加强地区安全和经济合作以及“涉及双方共同利益的诸多事宜”。 巴尔扎尼在另一份声明中强调，他支持叙利亚“保持统一和稳定”。 叙利亚库尔德武装主导的“叙利亚民主力量”长期控制叙北部和东部大片地区，去年3月与叙过渡政府签署相关协议，同意整合进国家机构，但协议的实施陷入僵局。双方在叙北部阿勒颇市爆发冲突，…"
