    "content": "新华社沈阳8月4日电 题：“东北超”点亮就业新解法 新华社记者刘艺淳、于也童 “边看球赛边投简历，很方便。”“直接留言问政策，这种体验太暖心了！”……首届东北地区城市足球联赛（简称“东北超”）第六轮比赛正在进行中，不少球迷在直播间这样留言。 借“东北超”东风，沈阳市委组织部、沈阳市人力资源和社会保障局依托“沈阳就业”抖音平台，抢抓赛前、赛中、赛后客流高峰时段，推出专属直播带岗活动。从“看球”到“找岗”，从“引客观赛”到“人才聚集”，沈阳推出“体育+就业+引才”跨界服务，在绿茵场外点亮就业新解法。 “东北超”市集上，…"
