    "title": "《给阿嬷的情书》在泰国首映",
    "link": "http://www.news.cn/20260804/55bcbacd1f3a4895bdf671d530edd1b7/c.html",
    "pub_date": "2026-08-04 21:02:53",
    "author": "林淑婷",
    "description": "新华社曼谷8月4日电（记者林淑婷 万后德）电影《给阿嬷的情书》3日晚在泰国曼谷举行首映礼，中泰两国政商、文化等各界人士出席观影。 《给阿嬷的情书》以“侨批”——南洋华侨漂洋过海的家书为线索，讲述了老一辈华侨下南洋谋生，与故乡亲人之间彼此牵挂、守望相助的故事。 导演蓝鸿春在曼谷首映仪式现场接受新华社记者采访时说，影片将故事背景设定在泰国，因为潮汕不少下南洋的故事都与泰国有关，而且泰国的唐人街充满烟火气。参演影片的泰籍演员乌萨·萨梅坎姆也出…",
    "content": "新华社曼谷8月4日电（记者林淑婷 万后德）电影《给阿嬷的情书》3日晚在泰国曼谷举行首映礼，中泰两国政商、文化等各界人士出席观影。 《给阿嬷的情书》以“侨批”——南洋华侨漂洋过海的家书为线索，讲述了老一辈华侨下南洋谋生，与故乡亲人之间彼此牵挂、守望相助的故事。 导演蓝鸿春在曼谷首映仪式现场接受新华社记者采访时说，影片将故事背景设定在泰国，因为潮汕不少下南洋的故事都与泰国有关，而且泰国的唐人街充满烟火气。参演影片的泰籍演员乌萨·萨梅坎姆也出席了首映礼。 中国驻泰国大使张建卫在致辞中表示，过去很多中国人漂洋过海来到泰国，…"
