    "author": "赵旭",
    "description": "新华社万象8月4日电（记者赵旭 马淮钊）国家烟草专卖局党组成员、副局长刘三江7月31日至8月2日率团访问老挝，就打击烟草制假走私等跨境犯罪、深化执法合作与老挝公安部开展专题交流。 双方一致同意，未来依托双边合作及澜湄执法安全合作框架，针对烟草非法贸易链条开展更具针对性的联合行动；加强中国卷烟商标知识产权保护与执法经验互鉴，携手维护两国烟草市场正常秩序，保障消费者合法权益。 刘三江表示，此次访问旨在落实中老两党两国最高领导人关于构建新时代…",
    "content": "新华社万象8月4日电（记者赵旭 马淮钊）国家烟草专卖局党组成员、副局长刘三江7月31日至8月2日率团访问老挝，就打击烟草制假走私等跨境犯罪、深化执法合作与老挝公安部开展专题交流。 双方一致同意，未来依托双边合作及澜湄执法安全合作框架，针对烟草非法贸易链条开展更具针对性的联合行动；加强中国卷烟商标知识产权保护与执法经验互鉴，携手维护两国烟草市场正常秩序，保障消费者合法权益。 刘三江表示，此次访问旨在落实中老两党两国最高领导人关于构建新时代全天候中老命运共同体的重要共识，聚焦烟草专卖品跨境非法贸易突出问题。中方感谢老方…"
